const inputData = $input.first().json;
const tenantId = inputData.tenant_id;
const contactId = inputData.contact_id;
const channelId = inputData.channel_id;

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!tenantId || !uuidRegex.test(String(tenantId).trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_TENANT_ID",
      message: "O parâmetro 'tenant_id' é obrigatório e deve ser um UUID válido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!contactId || !uuidRegex.test(String(contactId).trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_CONTACT_ID",
      message: "O parâmetro 'contact_id' é obrigatório e deve ser um UUID válido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!channelId || !uuidRegex.test(String(channelId).trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_CHANNEL_ID",
      message: "O parâmetro 'channel_id' é obrigatório e deve ser um UUID válido",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    is_valid: true,
    tenant_id: String(tenantId).trim(),
    contact_id: String(contactId).trim(),
    channel_id: String(channelId).trim()
  }
}];

const items = $input.all();
const first = items[0];

if (first.error) {
  return [{
    json: {
      status: "error",
      code: "DB_QUERY_ERROR",
      message: "Erro ao consultar conversa aberta no PostgreSQL",
      error_details: first.error.message || "Erro desconhecido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (items.length === 0 || !first.json || !first.json.conversation_id) {
  return [{
    json: {
      status: "success",
      code: "NOT_FOUND",
      found: false,
      message: "Nenhuma conversa aberta encontrada para este contato e canal",
      conversation: null,
      timestamp: new Date().toISOString()
    }
  }];
}

const conv = first.json;
return [{
  json: {
    status: "success",
    code: "CONVERSATION_FOUND",
    found: true,
    message: "Conversa aberta localizada com sucesso",
    conversation: {
      conversation_id: conv.conversation_id,
      tenant_id: conv.tenant_id,
      contact_id: conv.contact_id,
      channel_id: conv.channel_id,
      status: conv.status,
      assigned_user_id: conv.assigned_user_id || null,
      assigned_agent_id: conv.assigned_agent_id || null,
      ai_enabled: conv.ai_enabled,
      priority: conv.priority,
      last_message_at: conv.last_message_at,
      created_at: conv.created_at
    },
    timestamp: new Date().toISOString()
  }
}];
